LOAD DATA LOCAL INFILE 'F:/Work/Data Analyst/Projects/Power BI + MySQL/01_Healthcare_Operations_Analytics/Data/payments.csv' INTO TABLE payments CHARACTER SET utf8mb4 FIELDS TERMINATED BY ',' ENCLOSED BY '"' LINES TERMINATED BY '\r\n' IGNORE 1 LINES (@payment_id,@bill_id,@payment_date,@payment_amount,@payment_method,@payment_status,@reference_code) SET payment_id=NULLIF(@payment_id,''),bill_id=NULLIF(@bill_id,''),payment_date=NULLIF(@payment_date,''),payment_amount=NULLIF(@payment_amount,''),payment_method=NULLIF(@payment_method,''),payment_status=NULLIF(@payment_status,''),reference_code=NULLIF(@reference_code,'');
